"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["52214"],{86173(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.criterios_desempate_em_excesso","status":422,"titulo":"A ordem de desempate tem crit\xe9rios demais"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.criterios_desempate_em_excesso","requisitos":[],"oQueAconteceu":["A ordem de desempate do processo traz mais crit\xe9rios do que o limite de **20**. A\\nmensagem de detalhe diz o limite e quantos crit\xe9rios vieram. O limite \xe9 fixo do\\nsistema, e n\xe3o um valor que o processo configure. Na defini\xe7\xe3o dos crit\xe9rios o erro\\nvem com o campo `criterios`, e a recusa sai com **422** sem gravar nada.","A mesma confer\xeancia roda como defesa na publica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico,\\npara que um rascunho gravado antes do limite, ou por outro caminho, n\xe3o gere vers\xe3o\\npublicada."],"comoResolver":["Reduza a ordem de desempate a, no m\xe1ximo, 20 crit\xe9rios e reenvie\\n(`PUT /api/selecao/processos-seletivos/{id}/criterios-desempate`). Quando o erro vier\\nna publica\xe7\xe3o ou na retifica\xe7\xe3o, ajuste a ordem de desempate do processo e repita a\\nopera\xe7\xe3o."],"ondeAparece":["Defini\xe7\xe3o de crit\xe9rios de desempate do processo seletivo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);